BEGIN;

DO $$
BEGIN
  IF EXISTS (SELECT 1 FROM public.questions WHERE bank_version = 'v2.1') THEN
    RAISE EXCEPTION 'v2.1 question rows already exist; this migration is intended to run once';
  END IF;
END $$;

ON CONFLICT (id) DO UPDATE SET name=EXCLUDED.name, notes=EXCLUDED.notes, question_count=EXCLUDED.question_count, collision_count=EXCLUDED.collision_count;

ALTER TABLE public.questions ALTER COLUMN bank_version SET DEFAULT 'v2.1';
ALTER TABLE public.survey_responses ALTER COLUMN bank_version SET DEFAULT 'v2.1';
ALTER TABLE public.survey_results ALTER COLUMN bank_version SET DEFAULT 'v2.1';
ALTER TABLE public.survey_results ADD COLUMN IF NOT EXISTS response_coverage jsonb;
ALTER TABLE public.survey_results ADD COLUMN IF NOT EXISTS not_sure_count integer NOT NULL DEFAULT 0;

DROP POLICY IF EXISTS "Read questions policy" ON public.questions;
CREATE POLICY "Read questions policy" ON public.questions FOR SELECT USING (true);

UPDATE public.questions SET active = false WHERE bank_version = 'v2.0';




SELECT setval(pg_get_serial_sequence('public.questions','id'), GREATEST((SELECT max(id) FROM public.questions), 600), true);

SELECT setval(pg_get_serial_sequence('public.question_axis_links','id'), (SELECT max(id) FROM public.question_axis_links), true);


DO $$
DECLARE v_count integer;
BEGIN
  SELECT count(*) INTO v_count FROM public.questions WHERE active AND bank_version='v2.1';
  IF v_count <> 300 THEN RAISE EXCEPTION 'Expected 300 active v2.1 questions, found %', v_count; END IF;
  SELECT count(*) INTO v_count FROM public.question_axis_links l JOIN public.questions q ON q.id=l.question_id WHERE q.bank_version='v2.1';
  IF v_count <> 348 THEN RAISE EXCEPTION 'Expected 348 v2.1 links, found %', v_count; END IF;
  SELECT count(*) INTO v_count FROM public.question_metadata WHERE bank_version='v2.1';
  IF v_count <> 300 THEN RAISE EXCEPTION 'Expected 300 v2.1 metadata rows, found %', v_count; END IF;
  SELECT count(*) INTO v_count FROM public.questions WHERE bank_version='v2.1' AND text NOT LIKE '%In other words,%';
  IF v_count <> 0 THEN RAISE EXCEPTION 'Expected every v2.1 question to contain a plain-language restatement; % do not', v_count; END IF;
END $$;

COMMIT;
